-- file: a condition that reads other rows, run with the policy's rights wherever it is checked
CREATE FUNCTION authz_int."file__check_d17485e962"(p_row "fm"."files") RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT coalesce((fm.key_is_new(object_key)), false) FROM (SELECT (p_row).*) AS "files"
$f$;

-- file: a condition that reads other rows, run with the policy's rights wherever it is checked
CREATE FUNCTION authz_int."file__check_6fce862cc9"(p_row "fm"."files") RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT coalesce((object_key IN (SELECT v.object_key FROM fm.file_versions v WHERE v.file_id = files.id AND v.ready)), false) FROM (SELECT (p_row).*) AS "files"
$f$;

-- fm.folders: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE FUNCTION authz_int."fm.folders:seen"(p_id bigint) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = p_id)
      OR EXISTS (SELECT 1 FROM "fm"."folders" "folders" WHERE "folders"."id" = p_id
        AND (SELECT authz_int.scope_cmd('fm.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = "folders"."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = "folders"."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__view__has"("folders"."parent_id"))));
END $f$;

CREATE FUNCTION authz_gen."fm.folders:insert:items"(p_row "fm"."folders") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."fm.folders:seen"("folders"."id") THEN ARRAY[
    coalesce((coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    AND (coalesce((parent_id is null), false)
    OR authz_int."folder__edit__has"("folders"."parent_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('fm.folders', 'insert')), false),
    coalesce(true, false),
    coalesce((coalesce((parent_id is null), false)
    OR authz_int."folder__edit__has"("folders"."parent_id")), false),
    coalesce(coalesce((parent_id is null), false), false),
    coalesce(authz_int."folder__edit__has"("folders"."parent_id"), false),
    coalesce(coalesce("folders"."owner_id" = (SELECT authz.uid()), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[7]) END
  FROM (SELECT (p_row).*) AS "folders";
END;

CREATE FUNCTION authz_gen."fm.folders:update:items"(p_row "fm"."folders") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."fm.folders:seen"("folders"."id") THEN ARRAY[
    coalesce((coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = "folders"."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__edit__has"("folders"."parent_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('fm.folders', 'update')), false),
    coalesce(true, false),
    coalesce((coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = "folders"."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__edit__has"("folders"."parent_id"))), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM (SELECT (p_row).*) AS "folders";
END;

CREATE FUNCTION authz_gen."fm.folders:delete:items"(p_row "fm"."folders") RETURNS boolean[]
