-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'group' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "fm"."groups" o WHERE o."id" = v_uuid AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."group__admin" v WHERE v.id = o."id")
    OR authz_int."group__manage__has"(o."parent_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "fm"."group_members" o WHERE o."id" = v_bigint AND (authz_int."group__manage__has"(o."group_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (coalesce((inherit), false)
    AND authz_int."folder__share__has"(o."parent_id")))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__edit__has"(o."parent_id")))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__view__has"(o."parent_id")))));
        WHEN 'break_glass' THEN RETURN EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = v_bigint AND (coalesce((exists (select 1 from fm.users u where u.id = (SELECT authz.uid()) and u.is_support)), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "fm"."files" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__share__has"(o."folder_id"))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "fm"."files" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR authz_int."folder__edit__has"(o."folder_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "fm"."files" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__view__has"(o."folder_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'version' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "fm"."file_versions" o WHERE o."id" = v_bigint AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "fm"."file_versions" o WHERE o."id" = v_bigint AND (EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'group.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."groups" o
        WHERE o."id" > p_after::uuid AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."group__admin" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'membership.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."group_id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."group_id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."group_members" o
        WHERE o."id" > p_after::bigint AND (EXISTS (SELECT 1 FROM authz_int."group__manage__direct" v WHERE v.id = o."group_id")
    OR EXISTS (SELECT 1 FROM authz_int."group__manage" v WHERE v.id = o."group_id"))
        ORDER BY o."id" LIMIT p_limit;
