    OR EXISTS (SELECT 1 FROM authz_int."folder__share" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__share" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'file.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."files" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__share__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'version.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE o."id" > p_after::bigint AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'version.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "fm"."file_versions" o
        WHERE o."id" > p_after::bigint AND EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."folder__viewer__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'viewer: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'group' AND g.subject_relation = 'member' AND g.subject_id = ANY ((SELECT authz_int."group__member__ids"())::text[]) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'group' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."group__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'viewer: shared with' || ' group ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."group__member__why"(v_t.gid::uuid, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'link' AND g.subject_id = ANY ((SELECT authz.link_hashes())::text[]) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'viewer: shared by a link you presented' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'link' AND g.subject_id = ANY ((SELECT authz.link_hashes())::text[]) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold folder.viewer';
END $f$;

